import uuid
from datetime import UTC, datetime

from sqlalchemy import CheckConstraint
from sqlmodel import Field, SQLModel

from app.models.ttx_access import RoleEnum


class InvitationToken(SQLModel, table=True):
    """Redeemable exercise-enrollment token, generated by a Planner for
    a specific ttx_id + target role. Unlike a password, this is a shared
    join code meant to be handed out to many people over time (bounded by
    expiry/max_uses/revocation) rather than a one-time secret -- so the
    plaintext is persisted and stays visible/copyable in the audit list
    indefinitely, not hashed and shown only once.

    Multi-use up to max_uses (None = unlimited); redemption_count is a
    denormalized counter. Concurrent redemptions can't overshoot max_uses:
    the service reads the row `SELECT ... FOR UPDATE` before counting, and
    the CHECK below refuses any write that would go past it anyway.
    """

    __tablename__ = "invitation_token"
    __table_args__ = (
        CheckConstraint(
            "max_uses IS NULL OR redemption_count <= max_uses",
            name="ck_invitation_token_within_max_uses",
        ),
    )

    id: uuid.UUID = Field(default_factory=uuid.uuid4, primary_key=True)
    token: str = Field(unique=True, index=True, max_length=64)
    ttx_id: uuid.UUID = Field(foreign_key="ttx.id", index=True)
    role: RoleEnum
    description: str | None = Field(default=None, max_length=255)
    created_by_id: uuid.UUID = Field(foreign_key="user.id")
    expires_at: datetime
    max_uses: int | None = Field(default=None)
    redemption_count: int = Field(default=0)
    revoked_at: datetime | None = Field(default=None)
    created_at: datetime = Field(default_factory=lambda: datetime.now(UTC))
